import {
  getTextColor,
  hexToRgba,
  hexToRgbaObject,
  unHex,
  unHexAlpha,
} from '../';

describe('Color Utils', () => {
  const colors = {
    default: {
      hex: 'FFFFFFFF',
      rgbaVal: 'rgba(255, 255, 255, 1)',
      rgba: {
        r: 255,
        g: 255,
        b: 255,
        a: 1,
      },
    },
    blue: {
      hex: '0016FFFF',
      rgbaVal: 'rgba(0, 22, 255, 1)',
      rgba: {
        r: 0,
        g: 22,
        b: 255,
        a: 1,
      },
    },
    aqua: {
      hex: '#00FFFF66',
      rgbaVal: 'rgba(0, 255, 255, 0.4)',
      rgba: {
        r: 0,
        g: 255,
        b: 255,
        a: 0.4,
      },
    },
  };

  describe('unHex', () => {
    it('should unhex', () => {
      expect(unHex('FF')).toEqual(255);
    });

    it('should default', () => {
      expect(unHex()).toEqual(255);
    });
  });

  describe('unHexAlpha', () => {
    it('should unhex', () => {
      expect(unHexAlpha('FF')).toEqual(1);
    });

    it('should default', () => {
      expect(unHexAlpha()).toEqual(1);
    });
  });

  describe('hexToRgbaObject', () => {
    it('should convert hex to rgba object', () => {
      expect(hexToRgbaObject(colors.blue.hex)).toEqual(colors.blue.rgba);
      expect(hexToRgbaObject(colors.aqua.hex)).toEqual(colors.aqua.rgba);
    });

    it('should return the default value', () => {
      expect(hexToRgbaObject()).toEqual(colors.default.rgba);
    });
  });

  describe('hexToRgba', () => {
    it('should convert hex to rgba format', () => {
      expect(hexToRgba()).toEqual(colors.default.rgbaVal);
      expect(hexToRgba(colors.aqua.hex)).toEqual(colors.aqua.rgbaVal);
      expect(hexToRgba(colors.blue.hex)).toEqual(colors.blue.rgbaVal);
    });
  });

  describe('getTextColor', () => {
    it('should return white for dark color', () => {
      expect(getTextColor(colors.blue.hex)).toEqual('white');
    });

    it('should return black for light color', () => {
      expect(getTextColor(colors.blue.aqua)).toEqual('black');
      expect(getTextColor(colors.blue.default)).toEqual('black');
    });
  });
});
